  keywordstyle=\color{molblue},
  backgroundcolor=\color{callout!35!white},frame=l,
  rulecolor=\color{molblue!35!white},framesep=5pt,
  xleftmargin=6pt,xrightmargin=3pt,aboveskip=4pt,belowskip=3pt}

