\par\vspace{0.8em}
\refstepcounter{lstlisting}\label{lst:sos1api}
{\small\textbf{Listing~\thelstlisting:} The SOS1 movie as a readable protocol. Letters refer to Fig.~\ref{fig:sos1story}. Orange identifies graph edits, teal ligand placement, and purple receptor response; the text labels also carry the meaning. Angles are in degrees; distances are in angstroms unless stated otherwise.}\par
\begin{minipage}{\linewidth}
\sosstage{molblue}{A}{Prepare the starting hit}{Checkpoint 1: AXE supplies the starting graph and coordinates.}
\begin{lstlisting}[style=sosreadable]
designRoute.load("sos1-hit-only")                 # 5OVE / AXE
protein.prepare(pH=7.4, histidine=auto, ligand=CCD,
                repairMissingHeavy=true, gaps=cap, waters=retain)
pose.captureReference(mode=propagate)            # checkpoint 1: hit
\end{lstlisting}
\end{minipage}

\begin{minipage}{\linewidth}
\sosstage{sosedit}{B / C}{Change the scaffold, then propagate and relax}{Checkpoint 2: AWT (pyrazolylphenyl and 2-methyl). Checkpoint 3: AWZ (thiophene and merged bicyclic heterocycle). Search transfers the pose; subsequent local relaxation adjusts ligand and pocket.}
\begin{lstlisting}[style=sosreadable]
for step in [scaffold-rewrite, fragment-merge]:   # AWT, then AWZ
    designRoute.applyStep(step)
    pose.refine(searchChains=8, execution=serial, featureSeeding=v5)
    require complete coverage and feasible pose with retained core
    pose.apply(index=0)
    protein.parameterize()                      # no coordinate motion
    optimization.run(method=induced-fit-webgpu)
    require accepted relaxation, valence, and registered pose retention
    # checkpoints 2 and 3: relaxed AWT and AWZ
    pose.captureReference(mode=propagate)
\end{lstlisting}
\end{minipage}

\begin{minipage}{\linewidth}
\sosstage{sosedit}{D, first}{Install the AWW graph}{Checkpoint 4: introduce the benzyl-alcohol arm. This graph-only state precedes the placement shown in panel D.}
\begin{lstlisting}[style=sosreadable]
protein.parameterize()
designRoute.applyStep(open-phe890-pocket)         # checkpoint 4: AWW graph
protein.parameterize(); pose.captureReference(mode=propagate)
\end{lstlisting}
\end{minipage}

\begin{minipage}{\linewidth}
\sosstage{molteal}{D, then}{Specify and place the ligand arm}{Checkpoint 5 / panel D: same graph, new ligand geometry. Only the declared branch moves; Phe890 has not yet responded.}
\begin{lstlisting}[style=sosreadable]
pose.addContact(N7 donor -> Asn879.OD1)
pose.addContact(OX3 donor -> Tyr884.backboneO)
geometry.alignBranchToContact(target=Tyr884 contact, solution=best-directional,
    primary=C12--C15:+150, upstream=N7--C12:0..60,
    coupled=[CX4--CX5, CX15--CX16], donorHydrogen=search,
    allowedResponseAtoms=Phe890.[CG,CD1,CD2,CE1,CE2,CZ])
require no external coordinate targets, no internal severe clashes,
        and no overlaps outside the allowed Phe890 response atoms
pose.setDesignerLigandPoseFixed(true)            # checkpoint 5: ligand intent
\end{lstlisting}
{\small\textcolor{molteal}{\textbf{Readout:}} Tyr884 backbone contact achieved; clashes with the allowed Phe890 ring remain. This is a ligand hypothesis, not yet a clash-free complex.}
\end{minipage}

\begin{minipage}{\linewidth}
\sosstage{sosresponse}{E}{Test receptor responses to that fixed ligand}{Checkpoint 6: preserve the ligand graph and every ligand coordinate; change only the Phe890 conformation.}
\begin{lstlisting}[style=sosreadable]
protein.parameterize(); pose.setDesignerLigandPoseFixed(true)
for candidate in pose.enumerateSidechainRotamers(Phe890, maximum=64):
    pose.applySidechainRotamer(candidate)         # 13 states, including input
    inspect and retain ligand/pocket coordinates and severe-clash count
    calculation.run(job=energy, method=openmm,
                    solvent=OBC2, cutoff=1.0 nm, constraints=none)
    retain energy; require ligand coordinates unchanged
    history.undo(); verify restored ligand       # re-enumerate before next trial
# Source-run rule: lowest finite energy among zero-severe-clash states.
# The replay reapplies the recorded choice; publication verification
# requires it still to satisfy that rule under the fresh calculations.
pose.applySidechainRotamer(chi=[-180,90])          # checkpoint 6: Phe890 response
\end{lstlisting}
{\small\textcolor{sosresponse}{\textbf{Readout:}} Two of 13 states are clash-free; the recorded choice has the lower finite energy. The ligand remains unchanged.}
\end{minipage}

\begin{minipage}{\linewidth}
\sosstage{sosedit}{F}{Change the attachment while retaining a spatial feature}{Checkpoint 7: BAY-293. Move the thiophene attachment and replace the alcohol with an N-methylamine. Release the exact ligand lock, but retain the distal feature within its tolerance.}
\begin{lstlisting}[style=sosreadable]
protein.parameterize(); pose.setDesignerLigandPoseFixed(false)
pose.captureReference(mode=propagate)
designRoute.applyStep(finish-bay-293)              # AXH graph; retain distal
                                                 # seven-atom feature, RMSD <=2.25
pose.refine(searchChains=8, execution=serial, featureSeeding=v5)
require complete coverage, feasible pose, retained core and required feature
pose.apply(index=0); protein.parameterize()
optimization.run(method=induced-fit-webgpu)
require accepted relaxation, fixed-atom, valence, and feature-retention checks
# checkpoint 7: BAY-293; inspect and save the resulting ligand and pocket
\end{lstlisting}
{\small\textcolor{sosedit}{\textbf{Readout:}} Three of eight candidates are feasible; the selected, relaxed state passes the registered checks. Spatial retention is approximate, not an exact coordinate lock.}
\end{minipage}

\endgroup

The full \href{https://molarium.org/design-history/publications/sos1/designer-intent-2026-09-04/executable.action-script.json}{executable action script} contains 159 public actions with full selectors, arguments, and result expectations. Its runner stops on a failed action or expectation. It is distinct from the partial public-action segments attached to individual campaign commits. Parent-linked checkpoint snapshots preserve the saved molecular states, while the release also supplies numerical audits, including candidate coordinates, energies, and rejected alternatives. Thus the reading guide, executable procedure, and saved evidence serve different purposes; none alone is a complete account of the design process.
